mapper.select:
SELECT SM.INVOICE_DATE
FROM   SALES_MST SM
WHERE  SM.SALES_NO = #{salesNo}
AND    SM.COMPANY_CODE = #{companyCode}

SELECT FTAFM.FTA_CODE AS ftaCode ,FTAFM.SALES_NO AS salesNo ,FTAFM.SALES_SEQ AS salesSeq ,FTAFM.DIVISION_CODE AS divisionCode ,FTAFM.COMPANY_CODE AS companyCode ,FTAFM.PRODUCT_CODE AS productCode ,FTAFM.BIZ_PROJECT_CODE AS bizProjectCode ,FTAFM.INKOTERMS_TYPE AS inkotermsType ,FTAFM.DE_MINIMIS_INKOTERMS_TYPE AS deMinimisInkotermsType ,FTAFM.PRODUCT_UNIT AS productUnit ,FTAFM.PRODUCT_ASSETS_TYPE AS productAssetsType ,FTAFM.HS_CODE AS hsCode ,FTAFM.STANDARD AS standard ,FTAFM.WEIGHT AS weight ,FTAFM.AMOUNT AS amount ,FTAFM.NET_COST_AMOUNT AS netCostAmount ,FTAFM.EXWORK_AMOUNT AS exworkAmount ,FTAFM.FOB_AMOUNT AS fobAmount ,FTAFM.INAREA_AMOUNT AS originatingAmount ,FTAFM.OUTAREA_AMOUNT AS nonOriginatingAmount ,FTAFM.SP_COO_YN AS spCooYn ,FTAFM.WO_COO_YN AS woCooYn ,COALESCE(IHSC.HS_CODE_SUB_CATEGORY, '1') AS hsCodeSubCategory ,FTAFM.TARIFF_YN AS tariffYn FROM (SELECT FCRM.FTA_CODE AS FTA_CODE ,FCRM.SALES_NO AS SALES_NO ,FCRM.SALES_SEQ AS SALES_SEQ ,FCRM.DIVISION_CODE AS DIVISION_CODE ,FCRM.COMPANY_CODE AS COMPANY_CODE ,FCRM.PRODUCT_CODE AS PRODUCT_CODE ,FCRM.BIZ_PROJECT_CODE AS BIZ_PROJECT_CODE ,FM.INKOTERMS_TYPE AS INKOTERMS_TYPE ,FM.DE_MINIMIS_INKOTERMS_TYPE AS DE_MINIMIS_INKOTERMS_TYPE ,FCRM.PRODUCT_UNIT AS PRODUCT_UNIT ,FCRM.PRODUCT_ASSETS_TYPE AS PRODUCT_ASSETS_TYPE ,FCRM.HS_CODE AS HS_CODE ,FCRM.STANDARD AS STANDARD ,FCRM.WEIGHT AS WEIGHT ,FCRM.AMOUNT AS AMOUNT ,FCRM.NET_COST_AMOUNT AS NET_COST_AMOUNT ,FCRM.EXWORK_AMOUNT AS EXWORK_AMOUNT ,FCRM.FOB_AMOUNT AS FOB_AMOUNT ,FCRM.INAREA_AMOUNT AS INAREA_AMOUNT ,FCRM.OUTAREA_AMOUNT AS OUTAREA_AMOUNT ,FCRM.SP_COO_YN AS SP_COO_YN ,FCRM.WO_COO_YN AS WO_COO_YN ,CASE WHEN TD.HS_CODE IS NULL THEN 'N' ELSE 'Y' END AS TARIFF_YN FROM (SELECT FM.FTA_CODE AS FTA_CODE ,FM.SALES_NO AS SALES_NO ,FM.SALES_SEQ AS SALES_SEQ ,FM.DIVISION_CODE AS DIVISION_CODE ,FM.COMPANY_CODE AS COMPANY_CODE ,FM.PRODUCT_CODE AS PRODUCT_CODE ,FM.BIZ_PROJECT_CODE AS BIZ_PROJECT_CODE ,FM.PRODUCT_UNIT AS PRODUCT_UNIT ,FM.PRODUCT_ASSETS_TYPE AS PRODUCT_ASSETS_TYPE ,FM.HS_CODE AS HS_CODE ,FM.STANDARD AS STANDARD ,FM.WEIGHT AS WEIGHT ,FM.AMOUNT AS AMOUNT ,FM.NET_COST_AMOUNT AS NET_COST_AMOUNT ,FM.EXWORK_AMOUNT AS EXWORK_AMOUNT ,FM.FOB_AMOUNT AS FOB_AMOUNT ,FM.INAREA_AMOUNT AS INAREA_AMOUNT ,FM.OUTAREA_AMOUNT AS OUTAREA_AMOUNT ,FM.SP_COO_YN AS SP_COO_YN ,FM.WO_COO_YN AS WO_COO_YN ,SM.EXPORT_FLAG AS EXPORT_FLAG ,SM.INVOICE_DATE AS INVOICE_DATE ,SM.ARRIVAL_NATION AS ARRIVAL_NATION FROM FCR_MST FM INNER JOIN SALES_MST SM ON SM.SALES_NO = FM.SALES_NO AND SM.DIVISION_CODE = FM.DIVISION_CODE AND SM.COMPANY_CODE = FM.COMPANY_CODE WHERE FM.SALES_NO = #{salesNo} AND FM.COMPANY_CODE = #{companyCode} AND FM.PRODUCT_ASSETS_TYPE IN ('P', 'H')
AND FM.PRODUCT_CODE IN
#{productCode}
) FCRM INNER JOIN FTA_MASTER FM ON FM.FTA_CODE = FCRM.FTA_CODE AND FM.DELETE_YN <> 'Y' LEFT OUTER JOIN TARIFF_DIFFERENTIALS TD ON TD.FTA_CODE = FCRM.FTA_CODE AND TD.HS_CODE = FCRM.HS_CODE AND TD.NATION_CODE = CASE WHEN FCRM.EXPORT_FLAG = 'E' THEN FCRM.ARRIVAL_NATION ELSE TD.NATION_CODE END AND FCRM.INVOICE_DATE BETWEEN TD.APPLY_DATE AND TD.END_DATE ) FTAFM LEFT OUTER JOIN ITEM_HS_SUB_CATEGORY IHSC ON IHSC.ITEM_CODE = FTAFM.PRODUCT_CODE AND IHSC.DIVISION_CODE = FTAFM.DIVISION_CODE AND IHSC.COMPANY_CODE = FTAFM.COMPANY_CODE AND IHSC.FTA_CODE = FTAFM.FTA_CODE

mapper.delete:
DELETE FROM FCR_RESULT
WHERE  SALES_NO = #{salesNo}
AND    SALES_SEQ = #{salesSeq}
AND    FTA_CODE = #{ftaCode}
AND    COMPANY_CODE = #{companyCode}
